export function ColourToken({
  tokenName = "{{tokenName}}",
  value = "{{value}}",
  usage = "{{usage}}",
  showCode = {{showCode}},
}) {
  const preview = {
    background: { background: value, color: "#241430" },
    text: { background: "#ffffff", color: value, border: "1.5px solid #24143020" },
    border: { background: "#ffffff", color: "#241430", border: `4px solid ${value}` },
  }[usage];
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, maxWidth: 260, boxSizing: "border-box" }}>
      {showCode && (
        <code style={{ display: "block", marginBottom: 14, padding: "8px 10px", background: "#24143012", borderRadius: 6, font: "12px/1.4 ui-monospace, monospace", wordBreak: "break-all" }}>
          --{tokenName}: {value};
        </code>
      )}
      <div style={{ width: "100%", height: 72, borderRadius: 10, display: "grid", placeItems: "center", fontSize: 22, fontWeight: 600, boxSizing: "border-box", ...preview }}>Aa</div>
      <p style={{ margin: "10px 0 0", fontSize: 12, color: "#24143099" }}>{tokenName} &middot; applied as {usage}</p>
    </div>
  );
}
